// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); c.initialize(); }

    function testFuzz_property(address newOwner) public {
        // wide domain: newOwner may be anything, including address(0)
        address owner0 = c.owner();

        // step 1: current owner attempts to transfer ownership to the fuzzed address
        bool ok1;
        vm.prank(owner0);
        try c.transferOwnership(newOwner) { ok1 = true; } catch { ok1 = false; }

        // step 2: the original owner attempts a recoverable transfer to a nonzero address
        bool ok2;
        vm.prank(owner0);
        try c.transferOwnership(owner0) { ok2 = true; } catch { ok2 = false; }

        // Rule: a failed or non-zero transfer never destroys recoverability —
        // if the zero-address transfer succeeded, the owner must still be able to transfer.
        assertTrue(!ok1 || newOwner != address(0) || ok2);
    }
}
